SELECT (DATE_TRUNC('MONTH', "USAGE_DAY")) AS "TIME_BUCKET", SUM(CREDITS_BILLED) AS "CHARGEBACK_BUDGET_VARIANCE_CREDITS" FROM (SELECT "SERVICE_TYPE" AS SERVICE_TYPE, CAST("USAGE_DATE" AS DATE) AS USAGE_DAY, (CAST("CREDITS_USED_COMPUTE" AS DECIMAL(38, 9))) AS CREDITS_COMPUTE, (CAST("CREDITS_USED_CLOUD_SERVICES" AS DECIMAL(38, 9))) AS CREDITS_CLOUD_SERVICES_RAW, (CAST("CREDITS_ADJUSTMENT_CLOUD_SERVICES" AS DECIMAL(38, 9))) AS CREDITS_CLOUD_SERVICES_ADJUSTMENT, (CAST("CREDITS_USED_CLOUD_SERVICES" + "CREDITS_ADJUSTMENT_CLOUD_SERVICES" AS DECIMAL(38, 9))) AS CREDITS_CLOUD_SERVICES_BILLED, (CAST("CREDITS_USED" AS DECIMAL(38, 9))) AS CREDITS_USED, (CAST("CREDITS_BILLED" AS DECIMAL(38, 9))) AS CREDITS_BILLED FROM metering_daily_history) AS base GROUP BY (DATE_TRUNC('MONTH', "USAGE_DAY")) ORDER BY "CHARGEBACK_BUDGET_VARIANCE_CREDITS" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
